//! Ship engineers: where they are (`data/catalog/engineers.json`, generated by
//! `scripts/gen-starmap.py`), what they offer (`engineering.json`), and the commander's access
//! from the journal (`EngineerProgress`).
//!
//! Pinned blueprints are not tracked: the game does not log them. Remote crafts show up as
//! `EngineerCraft` like any other and update the fleet, so the plan and trip shrink on their own.

use crate::data;
use astromech_journal::JournalEvent;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;

#[derive(Debug, Clone, Deserialize)]
pub struct EngineerInfo {
    pub id: i64,
    pub name: String,
    pub system: String,
    pub id64: i64,
    pub coords: [f64; 3],
    #[serde(default)]
    pub colonia: bool,
}

#[derive(Deserialize)]
struct EngineersFile {
    engineers: Vec<EngineerInfo>,
}

pub fn catalog() -> &'static [EngineerInfo] {
    static C: std::sync::OnceLock<Vec<EngineerInfo>> = std::sync::OnceLock::new();
    C.get_or_init(|| {
        serde_json::from_str::<EngineersFile>(include_str!("../../../data/catalog/engineers.json"))
            .expect("engineers.json")
            .engineers
    })
}

/// Name → lowercase letters and digits ("Tod 'The Blaster' McQuinn" = "todtheblastermcquinn").
pub fn key(name: &str) -> String {
    name.chars().filter(|c| c.is_ascii_alphanumeric()).map(|c| c.to_ascii_lowercase()).collect()
}

pub fn info(name: &str) -> Option<&'static EngineerInfo> {
    let k = key(name);
    catalog().iter().find(|e| key(&e.name) == k)
}

/// Highest grade of `blueprint` that `engineer` offers on modules of `group` (0 if none).
pub fn offers(engineer: &str, blueprint: &str, group: &str) -> u8 {
    let k = key(engineer);
    let (Some((_, b)), Some(g)) = (data::blueprint(blueprint), data::group(group)) else { return 0 };
    b.grades
        .iter()
        .filter(|r| g.engineers_for(blueprint, r.grade).iter().any(|e| key(e) == k))
        .map(|r| r.grade)
        .max()
        .unwrap_or(0)
}

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct EngineerView {
    pub id: i64,
    pub name: String,
    pub system: String,
    pub coords: [f64; 3],
    pub colonia: bool,
    /// `Known`, `Invited`, `Acquainted`, `Unlocked`, or `Unknown` (never seen in the journal).
    pub progress: String,
    pub rank: Option<u8>,
    pub rank_progress: Option<u8>,
}

impl EngineerView {
    pub fn unlocked(&self) -> bool {
        self.progress.eq_ignore_ascii_case("Unlocked")
    }
}

const EVENTS: &[&str] = &["\"EngineerProgress\""];

#[derive(Debug, Default)]
pub struct EngineerBuilder {
    progress: HashMap<String, (String, Option<u8>, Option<u8>)>,
}

impl EngineerBuilder {
    pub fn apply(&mut self, ev: &JournalEvent) {
        if let JournalEvent::EngineerProgress { engineers } = ev {
            for e in engineers {
                self.progress.insert(key(&e.engineer), (e.progress.clone(), e.rank, e.rank_progress));
            }
        }
    }

    pub fn build(&self) -> Vec<EngineerView> {
        catalog()
            .iter()
            .map(|e| {
                let k = key(&e.name);
                let (progress, rank, rank_progress) =
                    self.progress.get(&k).cloned().unwrap_or_else(|| ("Unknown".into(), None, None));
                EngineerView {
                    id: e.id,
                    name: e.name.clone(),
                    system: e.system.clone(),
                    coords: e.coords,
                    colonia: e.colonia,
                    progress,
                    rank,
                    rank_progress,
                }
            })
            .collect()
    }
}

pub fn from_journal_dir(dir: &Path) -> Vec<EngineerView> {
    let mut b = EngineerBuilder::default();
    for p in astromech_journal::journal_logs(dir) {
        let Ok(text) = std::fs::read_to_string(&p) else { continue };
        for line in text.lines().filter(|l| EVENTS.iter().any(|e| l.contains(e))) {
            if let Ok(l) = astromech_journal::parse_line(line.trim()) {
                b.apply(&l.event);
            }
        }
    }
    b.build()
}
